import subprocess
# -*- coding: utf-8 -*- import os, torch, numpy as np, json import soundfile as sf from pyannote.audio import Model, Inference from sklearn.cluster import KMeans from pyannote.core import Annotation, Segment  def run_global_clustering_v2():     device = torch.device("cuda" if torch.cuda.is_available() else "cpu")     model_dir = r"E:\VideoTranslator_Project\models\pyannote"     model = Model.from_pretrained(model_dir)     model.to(device)          # 强制获取原始数据，不进行内部平均     inference = Inference(model, device=device)     v_src = r"C:\Users\Administrator\separated_audio\pure_vocals.wav"          print("[Cluster] 正在启动“时空大折叠”声纹扫描...")     wav, sr = sf.read(v_src)     if len(wav.shape) == 1: wav = np.expand_dims(wav, axis=0)     else: wav = wav.T     payload = {"waveform": torch.from_numpy(wav).float(), "sample_rate": sr}          res = inference(payload)     # res.data shape: (chunks, frames_per_chunk, speakers)          # --- 1. 时空缝合：将所有切片展平为一条直线 ---     chunks, local_frames, speakers = res.data.shape     # 我们采用简单的展平，虽然会有少许重叠，但对于聚类分析足够准确     flattened_data = res.data.reshape(-1, speakers)          # 2. 物理清洗：只保留活跃的发音帧     # 阈值设为 0.2，只要这 3 个坑位里有一个稍微有点声音，就参与聚类     active_mask = np.max(flattened_data, axis=1) > 0.2     active_features = flattened_data[active_mask]          print(f"[Cluster] 缝合完成。活跃样本数: {active_features.shape[0]}")      # 3. 核心聚类：强行分出 2 个人 (主讲人 + 那个男声)     print("[Cluster] 正在进行声纹基因分型...")     kmeans = KMeans(n_clusters=2, random_state=42, n_init=10)     cluster_labels = kmeans.fit_predict(active_features)      # 4. 结果溯源     annotation = Annotation()     # 映射回展平后的索引     labels_on_line = np.zeros(len(flattened_data), dtype=int) - 1     labels_on_line[active_mask] = cluster_labels          # 估算每一帧的时间 (总长 147s / 总帧数)     total_frames = flattened_data.shape[0]     frame_dur = 147.9 / total_frames          start_f = -1     for i in range(len(labels_on_line)):         l = labels_on_line[i]         if l != -1:             if start_f == -1: start_f = i             if i == len(labels_on_line)-1 or labels_on_line[i+1] != l:                 st = start_f * frame_dur                 et = i * frame_dur                 annotation[Segment(st, et)] = f"SPEAKER_{l:02d}"                 start_f = -1         else: start_f = -1      # 5. 汇报战果     roles = annotation.labels()     print("\n" + "🏆"*15)     print(f"定论报告：全局聚类成功！发现了 {len(roles)} 组独立声纹")     for role in roles:         dur = annotation.label_duration(role)         print(f"- {role}: 累积活跃时长 {dur:.2f} 秒")     print("🏆"*15)      # 采样两个角色的声音供验收     ffmpeg = r"C:\Users\Administrator\miniconda3\envs\blackwell_env\Lib\site-packages\static_ffmpeg\bin\win32\ffmpeg.exe"     for role in roles:         # 取该角色最响亮的片段         segments = list(annotation.label_timeline(role))         if segments:             # 选中间那个片段             target = segments[len(segments)//2]             out_wav = f"E:\\VideoTranslator_Project\\separated_audio\\cluster_{role}_sample.wav"             subprocess.run([ffmpeg, "-y", "-i", v_src, "-ss", str(target.start), "-t", str(min(5, target.duration)), out_wav], capture_output=True)             print(f"  -> {role} 样本已产出: {out_wav}")  if __name__ == "__main__":     run_global_clustering_v2()
